import {
	OAuthResourceServer,
	insufficientScope,
	type AuthorizationServerBinding,
} from "@cloudflare/workers-oauth-provider";
import { McpServer } from "@modelcontextprotocol/server";
import { createMcpHandler, getMcpAuthContext } from "agents/mcp/server";
import { env } from "cloudflare:workers";

type AuthProps = { userId: string };

interface Env {
	AUTH_SERVER: AuthorizationServerBinding<AuthProps>;
}

function createServer() {
	const server = new McpServer({ name: "my-mcp-server", version: "1.0.0" });
	const props = getMcpAuthContext()?.props as AuthProps;

	server.registerTool(
		"whoami",
		{ description: "Return the signed-in user" },
		async () => ({
			content: [{ type: "text", text: props.userId }],
		}),
	);

	return server;
}

const mcpHandler = createMcpHandler(createServer);

export default new OAuthResourceServer<Env, AuthProps>({
	resourceMetadata: {
		resource: env.MCP_SERVER_URL, // tokens for any other resource are rejected
		authorization_servers: [env.AUTH_SERVER_URL],
	},
	requiredScopes: ["mcp:read"],
	validateToken: (env) => env.AUTH_SERVER.validateToken,
	handler: {
		fetch(request, env, ctx) {
			// requiredScopes is advertised, not enforced: check it here.
			if (!ctx.auth.scope.includes("mcp:read")) {
				return insufficientScope(ctx.auth, ["mcp:read"]);
			}
			return mcpHandler(request, env, ctx);
		},
	},
});
```

The resource server passes the `props` stored with `completeAuthorization()` as `ctx.props`, and `getMcpAuthContext()` returns them inside your server:

```
interface McpAuthContext {
	props: Record<string, unknown>;
}
```

`getMcpAuthContext()` also works inside the server factory, so you can register tools based on who is signed in. When your own code authenticates the request instead of `OAuthResourceServer`, pass the identity with the `authContext` option:

```
import { McpServer } from "@modelcontextprotocol/server";
import { createMcpHandler, getMcpAuthContext } from "agents/mcp/server";
import { z } from "zod";

function createServer() {
	const server = new McpServer({ name: "my-server", version: "1.0.0" });
	const props = getMcpAuthContext()?.props;

	server.registerTool(
		"whoami",
		{ description: "Return the signed-in user" },
		async () => ({
			content: [{ type: "text", text: props?.userId ?? "anonymous" }],
		}),
	);

	// Only admins see this tool.
	if (props?.role === "admin") {
		server.registerTool(
			"deleteUser",
			{ description: "Delete a user", inputSchema: { userId: z.string() } },
			async ({ userId }) => ({
				content: [{ type: "text", text: `Deleted ${userId}` }],
			}),
		);
	}

	return server;
}

// Replace with your own session or token check.
async function authenticate(request) {
	if (request.headers.get("Authorization") === "Bearer dev-token") {
		return { userId: "user-123", role: "admin" };
	}
	return undefined;
}

export default {
	async fetch(request, env, ctx) {
		const props = await authenticate(request);
		if (!props) return new Response("Unauthorized", { status: 401 });

		return createMcpHandler(createServer, { authContext: { props } })(
			request,
			env,
			ctx,
		);
	},
};
```

```
import { McpServer } from "@modelcontextprotocol/server";
import { createMcpHandler, getMcpAuthContext } from "agents/mcp/server";
import { z } from "zod";

type Props = { userId: string; role: "admin" | "member" };

function createServer() {
	const server = new McpServer({ name: "my-server", version: "1.0.0" });
	const props = getMcpAuthContext()?.props as Props | undefined;

	server.registerTool(
		"whoami",
		{ description: "Return the signed-in user" },
		async () => ({
			content: [{ type: "text", text: props?.userId ?? "anonymous" }],
		}),
	);

	// Only admins see this tool.
	if (props?.role === "admin") {
		server.registerTool(
			"deleteUser",
			{ description: "Delete a user", inputSchema: { userId: z.string() } },
			async ({ userId }) => ({
				content: [{ type: "text", text: `Deleted ${userId}` }],
			}),
		);
	}

	return server;
}

// Replace with your own session or token check.
async function authenticate(request: Request): Promise<Props | undefined> {
	if (request.headers.get("Authorization") === "Bearer dev-token") {
		return { userId: "user-123", role: "admin" };
	}
	return undefined;
}

export default {
	async fetch(request, env, ctx) {
		const props = await authenticate(request);
		if (!props) return new Response("Unauthorized", { status: 401 });

		return createMcpHandler(createServer, { authContext: { props } })(
			request,
			env,
			ctx,
		);
	},
} satisfies ExportedHandler<Env>;
```

Props often hold upstream access tokens. Do not log or return them.

